code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Close horizontal bars where a zero gap is bounded by the same color.
    crossings = {}
    for r in range(h):
        for c in range(w):
            if g[r][c] != 0:
                continue
            left = c - 1
            while left >= 0 and g[r][left] == 0:
                left -= 1
            right = c + 1
            while right < w and g[r][right] == 0:
                right += 1
            if left >= 0 and right < w and g[r][left] == g[r][right]:
                color = g[r][left]
                g[r][c] = color
                crossings.setdefault(c, []).append((r, color))

    # Bottom vertical strokes are guides. Extend each one upward, with any
    # horizontal bar crossing it taking over the section above that crossing.
    for c in range(w):
        if g[h - 1][c] == 0:
            continue
        marker = g[h - 1][c]
        xs = sorted(crossings.get(c, []))
        if not xs:
            for r in range(h):
                if g[r][c] == 0:
                    g[r][c] = marker
            continue
        first_r, first_color = xs[0]
        for r in range(0, first_r + 1):
            g[r][c] = first_color
        for (r0, _), (r1, color) in zip(xs, xs[1:]):
            for r in range(r0 + 1, r1 + 1):
                g[r][c] = color
        last_r = xs[-1][0]
        for r in range(last_r + 1, h):
            g[r][c] = marker
    return g
'''
